-- ----------------------------
-- Table structure for wf_node_action
-- ----------------------------
DROP TABLE IF EXISTS `wf_node_action`;
CREATE TABLE `wf_node_action`  (
  `id` bigint(20) NOT NULL COMMENT 'primary key',
  `model_id` bigint(20) NOT NULL COMMENT 'model id',
  `model_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'model key',
  `model_version` int(11) NOT NULL COMMENT 'model version',
  `node_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'node id',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'node name',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'event type',
  `action_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'action type',
  `action_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'action config json',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'enabled',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `create_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'create user',
  `update_time` datetime NOT NULL COMMENT 'update time',
