-- ----------------------------
-- Table structure for wf_process_ext
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_ext`;
CREATE TABLE `wf_process_ext`  (
  `id` bigint(20) NOT NULL COMMENT 'primary key',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'flowable process instance id',
  `process_definition_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'process definition key',
  `business_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'business key',
  `starter_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'starter user id',
  `biz_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'business status',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `create_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'create user',
  `update_time` datetime NOT NULL COMMENT 'update time',
  `update_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'update user',
  `status` int(11) NOT NULL DEFAULT 1 COMMENT 'record status',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_process_definition_key`(`process_definition_key` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'flowable process extension table' ROW_FORMAT = DYNAMIC;

